function currency(n) {
  return `$${n.toFixed(2)}`;
}

function LayerMark({ size = 28, ringCount = 4, color = COLORS.accent }) {
  const rings = Array.from({ length: ringCount });
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" fill="none">
      {rings.map((_, i) => {
        const r = 4 + i * ((18 - 4) / (ringCount - 1));
        return (
          <circle
            key={i}
            cx="20"
            cy="20"
            r={r}
            stroke={color}
            strokeWidth="1.3"
            opacity={0.35 + (i / ringCount) * 0.65}
          />
        );
      })}
    </svg>
  );
}

