    sendEmailJS(EMAILJS_ADMIN_ALERT_TEMPLATE_ID, emailParams);
    sendEmailJS(EMAILJS_CUSTOMER_CONFIRM_TEMPLATE_ID, emailParams);

    setConfirmedOrder(order);
    setCart({});
